Found the bug: I hardcoded separator=2, but demo 2's separator is 9 (background 6), so my program collapsed it to one block and output [[1]]. The separator color must be detected dynamically (it's the color forming complete monochromatic lines). With that fixed, the rule (≥2 scattered markers → 1, else background) passes both demos and gives the test output [[1,1],[1,1],[1,4]].

```python
def transform(grid):
    H, W = len(grid), len(grid[0])
    sep = None
    for row in grid:
        if len(set(row)) == 1:
            sep = row[0]
            break
    rows = [i for i in range(H) if all(grid[i][j] == sep for j in range(W))]
    cols = [j for j in range(W) if all(grid[i][j] == sep for i in range(H))]
    from collections import Counter
    c = Counter(v for row in grid for v in row if v != sep)
    bg = c.most_common(1)[0][0]
    def bounds(vals, n):
        res, start = [], 0
        for v in vals:
            if v > start: res.append((start, v))
            start = v + 1
        if start < n: res.append((start, n))
        return res
    rb = bounds(rows, H)
    cb = bounds(cols, W)
    out = []
    for r0, r1 in rb:
        row = []
        for c0, c1 in cb:
            n = sum(1 for i in range(r0, r1) for j in range(c0, c1) if grid[i][j] not in (sep, bg))
            row.append(1 if n >= 2 else bg)
        out.append(row)
    return out
